import { NextResponse } from "next/server"
import connectDB from "@/lib/mongodb"
import Agent from "@/lib/models/agent"
import AgentWallet from "@/lib/models/agent-wallet"

// GET - Fetch all agents with optional status filter
export async function GET(request) {
  try {
    await connectDB()

    const { searchParams } = new URL(request.url)
    const status = searchParams.get("status") // pending, approved, rejected

    console.log("[Admin] Fetching agents with status:", status || "all")

    const filter = status ? { status } : {}
    const agents = await Agent.find(filter).sort({ createdAt: -1 })

    console.log(`[Admin] Found ${agents.length} agents`)

    return NextResponse.json({ success: true, agents })
  } catch (error) {
    console.error("[Admin] Error fetching agents:", error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

// POST - Approve or reject agent application
export async function POST(request) {
  try {
    await connectDB()

    const { agentId, action, commissionRate, currency } = await request.json()

    console.log("[Admin] Processing agent action:", { agentId, action })

    const agent = await Agent.findById(agentId)
    if (!agent) {
      return NextResponse.json({ success: false, error: "Agent not found" }, { status: 404 })
    }

    if (action === "approve") {
      agent.status = "approved"
      agent.commissionRate = commissionRate || 5 // Default 5%
      agent.currency = currency || "USD"
      await agent.save()

      // Create agent wallet
      const existingWallet = await AgentWallet.findOne({ agentId: agent._id })
      if (!existingWallet) {
        await AgentWallet.create({
          agentId: agent._id,
          balance: 0,
          reserved: 0,
          currency: agent.currency,
        })
        console.log("[Admin] Wallet created for agent:", agent._id)
      }

      console.log("[Admin] Agent approved:", agent.email)
    } else if (action === "reject") {
      agent.status = "rejected"
      await agent.save()
      console.log("[Admin] Agent rejected:", agent.email)
    } else {
      return NextResponse.json({ success: false, error: "Invalid action" }, { status: 400 })
    }

    return NextResponse.json({ success: true, agent })
  } catch (error) {
    console.error("[Admin] Error processing agent:", error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

// PATCH - Update agent settings
export async function PATCH(request) {
  try {
    await connectDB()

    const { agentId, updates } = await request.json()

    console.log("[Admin] Updating agent:", agentId, updates)

    const agent = await Agent.findByIdAndUpdate(agentId, updates, { new: true })

    if (!agent) {
      return NextResponse.json({ success: false, error: "Agent not found" }, { status: 404 })
    }

    console.log("[Admin] Agent updated:", agent.email)

    return NextResponse.json({ success: true, agent })
  } catch (error) {
    console.error("[Admin] Error updating agent:", error)
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}
